#!/usr/bin/env bash
# Regenerate the Android patch queue against clean upstream
# (android/UPSTREAM_COMMIT).
#
# The port is five independently-applicable slices generated by pathspec from
# one clean pinned tree. The slices are rebuilt from the current queue, so the
# file sets and hunk offsets stay exact. The 9x feature patch sits on top of the
# port result and is deliberately left untouched: its hunks are written against
# that result and cannot be expressed as an independent pathspec slice.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PATCH_DIR="$REPO_ROOT/android/patches"
PIN_FILE="$REPO_ROOT/android/UPSTREAM_COMMIT"

cd "$REPO_ROOT"

if [[ ! -f "$PIN_FILE" ]]; then
	echo "error: missing recorded upstream commit: $PIN_FILE" >&2
	exit 1
fi
upstream_commit=$(tr -d '[:space:]' < "$PIN_FILE")
if [[ ! "$upstream_commit" =~ ^[0-9a-f]{40}$ ]]; then
	echo "error: $PIN_FILE is not a 40-character commit SHA: $upstream_commit" >&2
	exit 1
fi

port_patches=(
	01-bionic-rust.patch
	02-native-ipc.patch
	03-termux-api.patch
	04-repo-root.patch
	05-android-motion.patch
)
feature_patch=90-isolation-retained.patch

for name in "${port_patches[@]}" "$feature_patch"; do
	if [[ ! -f "$PATCH_DIR/$name" ]]; then
		echo "error: missing patch: $PATCH_DIR/$name" >&2
		exit 1
	fi
done

echo "Regenerating Android port slices against clean upstream $upstream_commit..."

tmp=$(mktemp -d "${TMPDIR:-${PREFIX:?set PREFIX or TMPDIR}/tmp}/regen.XXXXXX")
trap 'rm -rf "$tmp"' EXIT
mkdir -p "$tmp/a" "$tmp/b" "$tmp/out"

# a = clean pinned upstream, b = the port result those slices must reproduce.
git archive "$upstream_commit" | tar -x -C "$tmp/a"
tar -C "$tmp/a" -cf - . | tar -C "$tmp/b" -xf -
for name in "${port_patches[@]}"; do
	git -C "$tmp/b" apply --whitespace=nowarn "$PATCH_DIR/$name"
done
# The feature patch is outside this generator. A stale 9x patch is a warning,
# not an abort: the standard slices are still valid and the file stays as is.
if ! git -C "$tmp/b" apply --check --whitespace=nowarn "$PATCH_DIR/$feature_patch"; then
	echo "warning: $feature_patch does not apply to the regenerated port result; leaving it untouched" >&2
fi

gen() { # name pathspec...
	local name=$1
	shift
	(cd "$tmp" && git diff --no-index --no-prefix a b -- "$@") > "$tmp/out/$name" || true
	if [[ ! -s "$tmp/out/$name" ]]; then
		echo "error: generated $name is empty; pathspec no longer matches the port" >&2
		exit 1
	fi
	echo "Staged $name ($(grep -c '^diff --git' "$tmp/out/$name") files)"
}

gen 01-bionic-rust.patch \
	crates \
	':(exclude)crates/natives/src/ipc' \
	':(exclude)crates/pi-natives/src/ipc'
gen 02-native-ipc.patch \
	crates/natives/src/ipc \
	crates/pi-natives/src/ipc \
	packages/natives/native/index.js \
	packages/natives/native/loader-state.js \
	packages/natives/scripts/gen-enums.ts \
	packages/natives/test/ipc.test.ts
gen 03-termux-api.patch \
	packages/coding-agent/src/cli/update-cli.ts \
	packages/coding-agent/src/main.ts \
	packages/coding-agent/src/modes/controllers \
	packages/coding-agent/src/slash-commands/builtin-collaboration.ts \
	packages/coding-agent/src/tools/ask.ts \
	packages/coding-agent/src/tools/browser/launch.ts \
	packages/coding-agent/src/utils/android-helpers.ts \
	packages/coding-agent/src/utils/clipboard.ts \
	packages/coding-agent/test/android-helpers.test.ts \
	packages/coding-agent/test/generator-android.test.ts \
	packages/coding-agent/test/termux-notifications.test.ts \
	packages/coding-agent/test/tools/browser-android-chromium.test.ts \
	packages/coding-agent/test/cli/update-cli.test.ts \
	packages/coding-agent/test/fixtures/browser-executable-probe.ts \
	packages/coding-agent/test/fixtures/clipboard-worker-copy.ts \
	packages/coding-agent/test/slash-commands/copy.test.ts \
	packages/coding-agent/test/utils/clipboard-osc52.test.ts \
	packages/coding-agent/test/utils/clipboard.test.ts \
	packages/tui/src/driver/session.ts
gen 04-repo-root.patch \
	packages/coding-agent/src/task/index.ts \
	packages/coding-agent/src/task/isolation-runner.ts \
	packages/coding-agent/src/task/structured-subagent.ts \
	packages/coding-agent/src/task/task-details.ts \
	packages/coding-agent/src/task/types.ts \
	packages/coding-agent/src/task/worktree.ts \
	packages/coding-agent/test/repo-root-isolation.test.ts
gen 05-android-motion.patch \
	packages/coding-agent/src/modes/settings.ts

# Completeness gate: the staged slices must reproduce the port tree exactly.
# A file dropped from every pathspec (rename, new path, typo) changes the tree
# and fails here before anything is written.
verify="$tmp/verify"
mkdir -p "$verify"
tar -C "$tmp/a" -cf - . | tar -C "$verify" -xf -
for name in "${port_patches[@]}"; do
	git -C "$verify" apply --whitespace=nowarn "$tmp/out/$name"
done
if ! git diff --no-index --quiet "$verify" "$tmp/b"; then
	echo "error: regenerated slices do not reproduce the port result; nothing written" >&2
	git diff --no-index --stat "$verify" "$tmp/b" >&2 || true
	exit 1
fi

cat > "$tmp/out/MANIFEST" <<'EOF'
# Active patch order: clean upstream -> 01..05 port slices -> 9x fork features
# Entries whose base name starts with 9 are fork features and are excluded
# from MANIFEST.standard.
# This manifest is validated by android/scripts/apply-patches.sh
01-bionic-rust.patch
02-native-ipc.patch
03-termux-api.patch
04-repo-root.patch
05-android-motion.patch
90-isolation-retained.patch
EOF

cat > "$tmp/out/MANIFEST.standard" <<'EOF'
# Standard patch order: clean upstream -> 01..05 port slices
# Must not list 9x fork feature patches; extended queue is MANIFEST.
# This manifest is validated by android/scripts/apply-patches.sh
01-bionic-rust.patch
02-native-ipc.patch
03-termux-api.patch
04-repo-root.patch
05-android-motion.patch
EOF

# Publish last: generation and verification failures leave the queue intact.
for name in "${port_patches[@]}" MANIFEST MANIFEST.standard; do
	mv "$tmp/out/$name" "$PATCH_DIR/$name"
done

echo "Manifests updated; $feature_patch left untouched."
echo "All port slices regenerated successfully."
